      "nodes": [
        {
          "node_id": "C1",
          "node_type": "concept",
          "capability_statement": "能辨识并解释 EXPLAIN 输出中 Seq Scan、Index Scan、Index Only Scan、Bitmap Index Scan、Bitmap Heap Scan、Filter 等节点代表的访问路径与代价含义。",
          "common_misconceptions": [
            "认为出现 Index Scan 就一定比 Seq Scan 快(小表或高选择性命中时未必)",
            "混淆 Bitmap Index Scan 与 Bitmap Heap Scan 的分工"
