        },
        {
          "node_id": "C4",
          "node_type": "concept",
          "capability_statement": "能解释单列索引、复合索引(列顺序)、部分索引(WHERE)、覆盖索引(INCLUDE) 在访问路径与代价上的差异。",
          "common_misconceptions": [
            "认为复合索引列顺序无关紧要(忽略等值-范围/依赖度规则)",
            "认为 INCLUDE 列会被单独索引并能支持其上的谓词过滤"
