        },
        {
          "node_id": "C6",
          "node_type": "concept",
          "capability_statement": "能解释 ANALYZE、pg_statistic、MCV/直方图与扩展统计(依赖度/多列) 如何影响估算与索引方案选择。",
          "common_misconceptions": [
            "认为统计信息总是准确且无需关注",
            "忽略多列相关性导致的估算偏差"
          ]
        },
        {
          "node_id": "R1",
          "node_type": "representation",
          "capability_statement": "能用 EXPLAIN (ANALYZE, BUFFERS) 获取执行计划，并按父子节点、loops、actual time 结构化解读计划树。",
          "common_misconceptions": [
            "只看顶层节点而不展开子节点",
            "忽略 BUFFERS(shared hit/read) 与 actual time 的代价定位"
          ]
        },
        {
          "node_id": "R2",
          "node_type": "representation",
          "capability_statement": "能把选择性表示为'命中行数/总行数'的比例，并据此估算候选索引的扫描代价。",
          "common_misconceptions": [
            "把选择性理解为返回行数的绝对值而非比例"
          ]
        },
        {
          "node_id": "S1",
          "node_type": "strategy",
          "capability_statement": "在解读计划时优先比较估算行数与实际行数，据此决定问题是缺索引还是统计信息陈旧。",
          "common_misconceptions": [
            "一看到慢就盲目加索引，忽略估算严重偏差指向统计信息问题"
